oxy_webhelp_navlinks = {"aws_evaluate_options_cloud_acc_setup-d39307e16421":{"topics":[{"title":"Manual versus CFT configuration for AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">A comparative overview of the manual and CloudFormation Template methods for adding         an AWS cloud account to <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/aws_manual_vs_cft_config_cld_acc.html","attributes":{"data-id":"aws_manual_vs_cft_config_cld_acc"},"menu":{"hasChildren":false},"tocID":"aws_manual_vs_cft_config_cld_acc-d39307e16438","topics":[]},{"title":"Supported AWS regions for CFT-based onboarding","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports a specific set of AWS regions for deploying         CloudFormation templates during the cloud account onboarding process.<\/p>","href":"saas\/aws_supported_regions_onboarding_cft.html","attributes":{"data-id":"aws_supported_regions_onboarding_cft"},"menu":{"hasChildren":false},"tocID":"aws_supported_regions_onboarding_cft-d39307e16452","topics":[]},{"title":"Multiple versus individual AWS cloud account addition","shortdesc":"<p class=\"shortdesc\">A comparative overview of multiple and individual addition of AWS cloud         accounts.<\/p>","href":"saas\/aws_multiple_vs_indv_acc_addition.html","attributes":{"data-id":"aws_multiple_vs_indv_acc_addition"},"menu":{"hasChildren":false},"tocID":"aws_multiple_vs_indv_acc_addition-d39307e16465","topics":[]},{"title":"Data scanning in AWS","shortdesc":"<p class=\"shortdesc\">When you enable data scanning in an AWS account, <span class=\"ph\">RSC<\/span> scans and         classifies your AWS data based on their sensitivity and generate intelligent insights. Data         scanning helps you manage cloud posture risks.<\/p>","href":"saas\/data_protection_insights_aws.html","attributes":{"data-id":"data_protection_insights_aws"},"menu":{"hasChildren":false},"tocID":"data_protection_insights_aws-d39307e16476","topics":[]},{"title":"AWS role chaining","shortdesc":"<p class=\"shortdesc\">With the AWS role chaining feature, <span class=\"ph\">RSC<\/span> introduces a dedicated AWS         account that serves as a centralized gateway to securely manage multiple AWS accounts from a         single administrative point.<\/p>","href":"saas\/aws_role_chaining.html","attributes":{"data-id":"aws_role_chaining"},"menu":{"hasChildren":false},"tocID":"aws_role_chaining-d39307e16490","topics":[]},{"title":"AWS multiple-role IAM architecture","shortdesc":"<p class=\"shortdesc\">With the multiple-role IAM architecture, <span class=\"ph\">RSC<\/span> provisions a dedicated         IAM role for each feature you enable instead of a single shared cross-account IAM         role.<\/p>","href":"saas\/aws_multi_role_architecture.html","attributes":{"data-id":"aws_multi_role_architecture"},"menu":{"hasChildren":false},"tocID":"aws_multi_role_architecture-d39307e16504","topics":[]}]}};